<?php
namespace App\Http\Controllers;use App\Models\{ComplaintType,Employee,EmployeeComplaint};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class ComplaintController extends Controller{public function index(Request $r){$q=EmployeeComplaint::with(['complainant','against','type','assignee'])->latest('complaint_date');$q->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('subject','like',"%$v%")->orWhereHas('complainant',fn($e)=>$e->where('name','like',"%$v%"))))->when($r->complaint_type_id,fn($q,$v)=>$q->where('complaint_type_id',$v))->when($r->from,fn($q,$v)=>$q->whereDate('complaint_date','>=',$v))->when($r->to,fn($q,$v)=>$q->whereDate('complaint_date','<=',$v))->when($r->status&&$r->status!=='All',fn($q)=>$q->where('status',$r->status));$counts=['All'=>EmployeeComplaint::count(),'Submitted'=>EmployeeComplaint::whereStatus('Submitted')->count(),'Under Investigation'=>EmployeeComplaint::whereStatus('Under Investigation')->count(),'Resolved'=>EmployeeComplaint::whereStatus('Resolved')->count(),'Dismissed'=>EmployeeComplaint::whereStatus('Dismissed')->count()];return view('complaints.index',['complaints'=>$q->paginate(10)->withQueryString(),'employees'=>Employee::orderBy('name')->get(),'types'=>ComplaintType::whereStatus(true)->orderBy('name')->get(),'counts'=>$counts]);}public function store(Request $r){$this->save($r,new EmployeeComplaint);return back()->with('success','Complaint created.');}public function update(Request $r,EmployeeComplaint $complaint){$this->save($r,$complaint);return back()->with('success','Complaint updated.');}public function status(Request $r,EmployeeComplaint $complaint){$complaint->update($r->validate(['status'=>'required|in:Submitted,Under Investigation,Resolved,Dismissed']));return back()->with('success','Complaint status updated.');}public function assign(Request $r,EmployeeComplaint $complaint){$complaint->update($r->validate(['assigned_to'=>'required|exists:employees,id','resolution_deadline'=>'nullable|date']));if($complaint->status==='Submitted')$complaint->update(['status'=>'Under Investigation']);return back()->with('success','Complaint assigned.');}public function resolve(Request $r,EmployeeComplaint $complaint){$d=$r->validate(['resolution_type'=>'required|string|max:100','investigation_notes'=>'required|string|max:3000','resolution_action'=>'required|string|max:3000','resolution_date'=>'required|date','follow_up_action'=>'nullable|string|max:3000','follow_up_date'=>'nullable|date']);$d['status']='Resolved';$complaint->update($d);return back()->with('success','Complaint resolved.');}public function followUp(Request $r,EmployeeComplaint $complaint){$complaint->update($r->validate(['follow_up_action'=>'required|string|max:3000','follow_up_date'=>'required|date','feedback'=>'nullable|string|max:3000']));return back()->with('success','Follow-up updated.');}public function document(EmployeeComplaint $complaint){abort_unless($complaint->document_path&&Storage::disk('public')->exists($complaint->document_path),404);return Storage::disk('public')->response($complaint->document_path);}public function destroy(EmployeeComplaint $complaint){if($complaint->document_path)Storage::disk('public')->delete($complaint->document_path);$complaint->delete();return back()->with('success','Complaint deleted.');}private function save(Request $r,EmployeeComplaint $c):void{$d=$r->validate(['complainant_id'=>'nullable|required_unless:is_anonymous,1|exists:employees,id','against_id'=>'nullable|different:complainant_id|exists:employees,id','complaint_type_id'=>'required|exists:complaint_types,id','subject'=>'required|string|max:191','complaint_date'=>'required|date','description'=>'required|string|max:3000','document'=>'nullable|file|mimes:pdf,jpg,jpeg,png,doc,docx|max:5120','is_anonymous'=>'nullable|boolean']);unset($d['document']);$d['is_anonymous']=$r->boolean('is_anonymous');if($d['is_anonymous'])$d['complainant_id']=null;if($r->hasFile('document')){if($c->document_path)Storage::disk('public')->delete($c->document_path);$d['document_path']=$r->file('document')->store('complaints','public');}$c->fill($d)->save();}}
